import pages as PG
from pages import *
from pages import foreword,glance,reading,story,cards,end,sources,build,covart,verse
from fx import *
import math
PG.configure('/festivals/makara-sankranti/',[('','Makara Saṅkrānti','The Sun Turns North')],'navy','Makara Saṅkrānti','Lord','Saṅkrānti')
PG.CFG.update(backurl='/festivals/',backname='all festivals')
PG.OUT='outd/makara-sankranti/'
i=0
def sugarcane(): return '<path d="M0 0 v-80" stroke="#7a9a3a" stroke-width="7"/>'+''.join(f'<path d="M-4 -{k*16} h8" stroke="#4a6a2a" stroke-width="2"/>' for k in range(1,5))+'<path d="M0 -80 q-20 -10 -26 -30 M0 -80 q18 -14 22 -32" stroke="#3a9a4a" stroke-width="3" fill="none"/>'
def ellu(): return plate()+''.join(f'<circle cx="{x}" cy="{y}" r="2.2" fill="#fff" stroke="#888" stroke-width=".5"/>' for x,y in [(-10,-6),(-4,-8),(2,-6),(8,-8),(-6,-3),(5,-3),(0,-10)])+'<rect x="10" y="-14" width="10" height="8" fill="#b5651d"/>'
def kite(c='#c0392b'): return f'<path d="M0 -30 l18 22 l-18 30 l-18 -30z" fill="{c}"/><path d="M0 22 q10 20 -6 40" fill="none" stroke-width="1.2"/>'
def zodiac(hi=9):
    o='<circle r="62" fill="#fff8e7"/><circle r="40" fill="#fde9c8"/>'
    for k in range(12):
        a=(k*30-90)*math.pi/180; o+=f'<path d="M{40*math.cos(a):.1f} {40*math.sin(a):.1f} L{62*math.cos(a):.1f} {62*math.sin(a):.1f}" stroke-width="1.5"/>'
        if k==hi:
            a2=(k*30-75)*math.pi/180; o+=f'<circle cx="{51*math.cos(a2):.1f}" cy="{51*math.sin(a2):.1f}" r="9" fill="#ffd60a"/>'
    return o
def arrowbed(): return '<rect x="-60" y="-10" width="120" height="8" fill="#8a5a3a"/>'+''.join(f'<path d="M{x} -2 l{(-1)**int(x/10)*6} 28" stroke-width="1.6"/>' for x in range(-56,60,8))+'<path d="M-50 -16 h90" stroke="#c98a5a" stroke-width="10"/><circle cx="48" cy="-18" r="9" fill="#f2c79b"/><path d="M40 -26 q8 -10 16 0" fill="#eee"/>'
def gangariver(): return '<path d="M-70 -80 q30 40 0 80 q-20 30 30 40" fill="none" stroke="#8fb8de" stroke-width="18"/>'
COV=covart('The sun rising over fields of sugarcane, kites in the sky, a plate of sesame and jaggery and a decorated cow',f'<rect width="440" height="196" fill="#fde9c8"/>'+g(220,120,1.6,sun(30))+'<rect y="150" width="440" height="46" fill="#cfe0b8"/>'+''.join(g(x,190,.9,sugarcane()) for x in (30,55,80,385,410))+g(150,60,1,kite())+g(300,45,.9,kite('#2a5aa8'))+g(340,80,.7,kite('#e0a800'))+g(170,192,1.4,ellu())+g(300,192,1.1,cow()))
pp=[foreword(i,['Almost every Hindu festival follows the moon. <b>Makara Saṅkrānti</b> follows the sun: it is the day the sun enters the sign of Makara (Capricorn), which is why it falls on almost the same date every January. It is the start of the sun’s “northern course”, a harvest festival, and a day for bathing in sacred rivers.','In Karnataka it is the day of <b>ellu-bella</b>: plates of sesame, jaggery, coconut and sugar figures carried from house to house with the words “eat sesame and jaggery, and speak sweetly”. Villages also wash and decorate the cattle and, in places, lead them over a fire.','This article explains the astronomy honestly, tells the stories (Bhīṣma waiting on his bed of arrows, the Gaṅgā reaching the sea, the Sun visiting Śani), gives the verses, and goes round India from Pongal to Lohri to the kites of Gujarat.'],[('z','Why is Saṅkrānti always on the 14th or 15th of January?'),('b','Because it follows the sun, Zappy, not the moon. Every other festival wanders; this one keeps its appointment.')]),
 glance([('Name','Makara Saṅkrānti; Saṅkrānti or Suggi habba (Karnataka); Pongal (Tamil Nadu); Lohri, Maghi (Punjab); Magh Bihu (Assam); Uttarāyaṇ (Gujarat)'),('When','The sun’s entry into Makara, sidereal Capricorn; 14 January, sometimes 15'),('Meaning','Start of uttarāyaṇa, the “northern course”, in traditional reckoning; harvest; the month of Māgha begins'),('Deity','Sūrya, the Sun; also Viṣṇu and Lakṣmī; cattle'),('Karnataka','Ellu bīruvudu, sakkare acchu, sugarcane; cattle washed and decorated; kicchu hāyisuvudu in villages'),('Bathing','Gaṅgāsāgar, Prayāga (Māgha Meḷa), river confluences'),('Stories','Bhīṣma; Bhagīratha’s Gaṅgā at the sea; Sūrya and Śani')],svg(560,140,'The sun moving into the Capricorn sign on a zodiac wheel',f'<rect width="560" height="140" fill="#fffaf0"/>'+g(280,70,1,zodiac())+lab(440,70,'Makara'))),
 reading('sun','WHAT “SAṄKRĀNTI” MEANS','The sun changes house',svg(560,170,'A zodiac wheel with the sun stepping from Dhanus into Makara',f'<rect width="560" height="170" fill="#fffaf0"/>'+g(200,85,1.25,zodiac())+''.join(lab(400,30+k*24,t) for k,t in enumerate(['12 rāśis, 12 saṅkrāntis','Dhanus → Makara','= Makara Saṅkrānti','Māgha begins','solar, so a fixed date']))),['<b>The word.</b> <i>Saṅkrānti</i> means “crossing over”: the moment the sun passes from one sign of the zodiac (<b>rāśi</b>) into the next. There are twelve in a year. The crossing into <b>Makara</b> (Capricorn) is the one India celebrates most.','<b>A solar festival.</b> Because it follows the sun through the sidereal zodiac, its date in the Gregorian calendar barely moves: 14 January, sometimes 15. The lunar festivals, which follow the moon, wander by weeks from year to year.','<b>Uttarāyaṇa.</b> Tradition calls this day the start of <b>uttarāyaṇa</b>, the sun’s northern course, the auspicious half of the year when the days lengthen. Strictly, the sun turns north at the winter solstice, around 21–22 December; because the equinoxes slowly drift (precession), the solstice and Makara Saṅkrānti, which once fell together about 1,700 years ago, are now over three weeks apart.','<b>Puṇya-kāla.</b> The hours around the crossing are counted especially holy for bathing and giving; almanacs give the exact moment.'],[('z','So uttarāyaṇa started weeks ago?'),('b','Astronomically, yes, Zappy. The festival keeps the old reckoning. Honest almanacs mention both.')],'The sun <b>crosses into Makara</b>.'),
 verse('v-gita','Bhagavad Gītā 8.24','The bright path',['agnir jyotir ahaḥ śuklaḥ ṣaṇmāsā uttarāyaṇam','tatra prayātā gacchanti brahma brahmavido janāḥ'],svg(200,150,'A bright upward path from fire to sun',f'<rect width="200" height="150" fill="#fde9c8"/>'+g(40,140,1,lamp())+'<path d="M50 120 q60 -40 110 -90" stroke="#ffd60a" stroke-width="8" fill="none"/>'+g(165,32,1,sun(16))),'Fire, light, the day, the bright fortnight, the six months of the northern course: those who know Brahman and depart at that time go to Brahman.',[('agniḥ jyotiḥ','fire, light'),('ahaḥ','the day'),('śuklaḥ','the bright fortnight'),('ṣaṇ-māsāḥ','six months'),('uttarāyaṇam','the northern course'),('brahma-vidaḥ','knowers of Brahman')],'<b>Why uttarāyaṇa matters.</b> In chapter 8 Kṛṣṇa describes two paths for the departing soul: the bright path of light and the northern course, which does not return, and the dark path that does. This verse made the northern half of the year the auspicious half. Many teachers read “light, day, bright fortnight” as states of knowledge rather than calendar dates. (Interpretation.)',k='The year’s <b>bright half</b> begins.',note='Text: Bhagavad Gītā 8.24, BBT edition (prabhupadabooks.com), set in IAST. Read the whole chapter on our '+L('/vishnu/bhagavad-gita/','Gītā pages')+'.'),
 story('bhishma','BHĪṢMA WAITS FOR THE SUN','The bed of arrows',strip('Three panels: Bhīṣma falling in battle pierced by arrows; lying on a bed of arrows teaching Yudhiṣṭhira; departing as the sun turns north',[panel([(god('#e0e0e0'),1),(bow(),1)],'#fde4e4',150),panel([(arrowbed(),.9),(god('#c0392b'),.7)],'#fff3cf',150),panel([(arrowbed(),.8),(sun(16),1.2)],'#fde9c8',150)],['the fall','teaching from the bed','the sun turns']),'The Mahābhārata’s most famous death, told in the Bhīṣma and Anuśāsana parvans.',['<b>Bhīṣma</b>, grandsire of the Kurus, had a boon from his father: he would die only when he chose (<i>icchā-mṛtyu</i>).','On the tenth day of the Kurukṣetra war, Arjuna’s arrows brought him down. So many arrows had pierced him that his body did not touch the ground: he lay on a <b>bed of arrows</b>.','It was the southern half of the year, dakṣiṇāyana. Bhīṣma refused to die then and waited, in pain, for the sun to turn north.','During those weeks, with Kṛṣṇa beside him, he taught Yudhiṣṭhira on kingship, dharma and liberation: the Śānti and Anuśāsana parvans, and the '+L('/vishnu/vishnu-sahasranama/','Viṣṇu Sahasranāma')+'.','When uttarāyaṇa came, Bhīṣma gave up his life by his own will, meditating on Kṛṣṇa. The day he departed is kept as Bhīṣma Aṣṭamī in Māgha; Saṅkrānti remembers the turning he waited for.'],[('z','He waited weeks on arrows?'),('b','For the right moment, Zappy. And he spent the waiting teaching. That’s the grandsire.')],'Waiting <b>for the light</b>.'),
 story('ganga','THE GAṄGĀ REACHES THE SEA','Bhagīratha and Gaṅgāsāgar',strip('Three panels: Bhagīratha in penance; the Gaṅgā falling on Śiva’s head; the river reaching the sea at Kapila’s hermitage',[panel([(sage('#ff8c1a'),1.1)],'#fff3cf',150),panel([(shiva(),.9),(gangariver(),.6)],'#dfe9f6',150),panel([(river(144,110),1),(sage('#2a5aa8'),.8)],'#dfe9f6',None)],['Bhagīratha’s tapas','Śiva holds the river','the sea at last']),'Told in the Rāmāyaṇa (Bāla Kāṇḍa) and the Bhāgavata Purāṇa (book 9).',['The sixty thousand sons of King <b>Sagara</b>, searching for a sacrificial horse, disturbed the sage <b>Kapila</b> in his meditation and were burned to ash.','Only the waters of the heavenly <b>Gaṅgā</b> could free their souls. Generations tried; at last their descendant <b>Bhagīratha</b> won her with fierce penance.','The falling river would have shattered the earth, so Śiva caught her in his matted hair and let her down gently.','Bhagīratha led the Gaṅgā across the land to the sea, to the place where his ancestors’ ashes lay. Her waters touched them and they rose to heaven.','That meeting of river and ocean is <b>Gaṅgāsāgar</b> in Bengal, where lakhs of pilgrims bathe on Makara Saṅkrānti at the temple of Kapila Muni.'],[('z','Bhagīratha prayatna: that’s from here?'),('b','Yes, Zappy. A “Bhagīratha effort” means a task that takes generations and finally succeeds.')],'A river brought <b>home to the sea</b>.'),
 story('shani','THE SUN VISITS HIS SON','Sūrya and Śani',strip('Three panels: the Sun and his dark son Śani estranged; the Sun arriving at Śani’s house in Makara; Śani offering black sesame',[panel([(sun(20),1.3),(god('#2a2a3a'),.9)],'#e9e3f5',150),panel([(sun(20),1.2),(palace(),.5)],'#fde9c8',150),panel([(god('#2a2a3a'),.9),(ellu(),1.2)],'#fff3cf',150)],['father and son','the visit','black sesame']),'A popular story, told to explain the sesame; not from one fixed text.',['<b>Śani</b> (Saturn) is the son of Sūrya and Chāyā; father and son were said to be on poor terms.','In astrology Makara is Śani’s own sign. When the sun enters it, the father, as it were, comes to stay at his son’s house.','The story says Śani received his father with what he had: <b>black sesame</b>.','Pleased, Sūrya blessed him, and the visit mended the relationship.','So sesame is the food of the day: offered, eaten, given away, and used in the bath water. Its moral is the Karnataka greeting: eat sweet, speak sweet, let quarrels end.'],[('z','Father and son made up over sesame?'),('b','Sometimes all it takes is a small gift and a visit, Zappy. That’s the ellu-bella idea.')],'A visit that <b>ends a quarrel</b>.'),
 verse('v-surya','Navagraha Stotra, verse 1','The Sun saluted',['japākusumasaṅkāśaṃ kāśyapeyaṃ mahādyutim','tamo’riṃ sarvapāpaghnaṃ praṇato’smi divākaram'],svg(200,150,'A red hibiscus beside the rising sun',f'<rect width="200" height="150" fill="#fde9c8"/>'+g(120,95,1.4,sun(26))+g(50,120,1.4,lotus('#e0306a','#c0392b'))),'I bow to the maker of the day, red like the hibiscus flower, son of Kaśyapa, of great radiance, the enemy of darkness, destroyer of all sin.',[('japā-kusuma','the hibiscus flower'),('saṅkāśam','resembling'),('kāśyapeyam','son of Kaśyapa'),('mahā-dyutim','of great radiance'),('tamo-’rim','enemy of darkness'),('divākaram','maker of the day')],'<b>The Sun’s day.</b> Saṅkrānti is the Sun’s own festival, so many homes begin it with this verse, the first of the Navagraha Stotra attributed to Vyāsa, and offer water (<i>arghya</i>) to the rising sun. In Tamil Nadu the new rice is cooked in the open, facing the sun, for Pongal. Many also recite the Āditya Hṛdayam this day.',k='Salute the <b>enemy of darkness</b>.',note='Text as on hindutone.com and sanskritdocuments.org (Vyāsa’s Navagraha Stotra), set in IAST.'),
 cards('karnataka','ELLU BĪRUVUDU','Karnataka’s sesame exchange',fig_row('A plate of ellu-bella, sugar figures, sugarcane and a banana',[(ellu(),1.6),('<path d="M-10 0 l4 -24 h12 l4 24z" fill="#fff"/><circle cy="-30" r="7" fill="#fff"/>',1.3),(sugarcane(),1),(banana(),1.6)],['ellu-bella','sakkare acchu','kabbu','bāḷe haṇṇu'],gy=150),[('🥥','The mix','<b>Ellu-bella</b>: white sesame, jaggery cut small, dry coconut, roasted gram and groundnut, mixed by hand for days before.'),('🍬','Sakkare acchu','Moulded sugar figures of animals, temples and gods, white and pink, made at home or bought, are added to the plate.'),('🚶','Bīruvudu','Girls and women dress in new clothes and carry the plates to friends’ and relatives’ houses, exchanging a handful with sugarcane and a banana, saying “<b>ellu bella tindu oḷḷe mātāḍi</b>”: eat sesame and jaggery, speak good words.'),('👶','Little ones','In many homes, especially Telugu-speaking families in Karnataka, small children get <b>bhogi pallu</b>: jujube berries, coins and flowers poured over the head for health and an evening ārati. (Customs vary.)')],[('z','Do boys go too?'),('b','Everyone can, Zappy, but the girls run the show. The exchange is how friendships are renewed each year.')],'Eat sweet, <b>speak sweet</b>.'),
 reading('cattle','SUGGI AND THE CATTLE','Harvest in the villages',svg(560,170,'Decorated cattle leaping over a small fire while villagers watch, with haystacks behind',f'<rect width="560" height="170" fill="#fde9c8"/>'+'<rect y="135" width="560" height="35" fill="#e9d6c0"/>'+''.join(g(x,135,1,'<path d="M-30 0 q30 -60 60 0z" fill="#e0c060"/>') for x in (60,500))+g(250,140,1,fire())+g(250,90,1.1,cow())+g(380,140,1,person('#c0392b'))+g(430,140,1,person('#2a5aa8'))),['<b>Suggi habba.</b> In farming Karnataka, Saṅkrānti is the <b>suggi</b>, harvest, festival. The new paddy, ragi and sugarcane are in; the threshing floor is worshipped; the first rice is cooked with jaggery as <b>huggi</b> or pongal.','<b>The cattle.</b> Cows and bullocks are bathed, their horns painted and capped with brass, decorated with bells, garlands and coloured cloth, fed pongal and sugarcane, and worshipped as the farm’s partners.','<b>Kicchu hāyisuvudu.</b> In villages of Old Mysore, Maṇḍya and Hāsana, the decorated cattle are made to run or leap across a bed of burning hay in the evening: <b>kicchu hāyisuvudu</b>, “crossing the fire”, believed to protect them from disease. It is a spectacle the whole village watches. (Animal welfare groups now urge care.)','<b>Rangoli.</b> The rangoli of Saṅkrānti morning is the largest of the year, and in the north of the state jōḷada rotti, ellu-hacchida rotti and seasonal vegetables fill the plate.'],[('z','Doesn’t the fire hurt them?'),('b','It’s brief and the hay burns low, Zappy, but care is everything. Many villages now keep it symbolic.')],'The harvest thanks <b>its partners</b>.'),
 cards('india','ONE SUN, MANY FESTIVALS','Pongal, Lohri, Bihu and the kites',fig_row('A pongal pot boiling over, a bonfire, kites and a bowl',[(pot_rice(),1.5),(fire(),1),(kite(),1.3),(kite('#2a5aa8'),1.1)],['Pongal','Lohri','Uttarāyaṇ','kites'],gy=150),[('🍚','Tamil Nadu','<b>Pongal</b>, four days: Bhogi (burning the old), Pongal (new rice boiled over in the open, facing the sun, with the cry “pongalo pongal”), Māṭṭu Pongal (the cattle), Kāṇum Pongal (visits).'),('🔥','Punjab and Haryana','<b>Lohri</b> the night before, with a bonfire, rewri and popcorn thrown in, songs and dances; the next day is Maghi.'),('🪁','Gujarat and Rajasthan','<b>Uttarāyaṇ</b>: the whole sky full of kites from dawn, rooftop parties, undhiyu and chikki.'),('🌾','Assam and beyond','<b>Magh Bihu</b>: community feasts and the burning of the Meji hut; Poush Saṅkrānti in Bengal with date-palm jaggery and piṭhā; Makaravilakku at Śabarimala in Kerala.')],[('z','Kites for the sun?'),('b','Everyone up on the roof in the winter sunshine, Zappy. Some say the old idea was simply to get your share of the sun.')],'The whole of India <b>faces the sun</b>.'),
 reading('bathing','THE GREAT BATHS','Rivers, confluences and the Māgha Meḷa',svg(560,170,'Pilgrims bathing where two rivers meet, with flags and a rising sun',f'<rect width="560" height="170" fill="#fde9c8"/>'+g(450,60,1,sun(22))+'<path d="M0 100 q140 20 280 50 L560 120 v50 h-560z" fill="#8fb8de"/><path d="M0 140 q200 -10 280 10" stroke="#5a8ab8" stroke-width="6" fill="none"/>'+''.join(g(x,150,.8,person(c)) for x,c in [(160,'#c0392b'),(220,'#e0a800'),(330,'#2a5aa8')])+g(100,90,1,flag())),['<b>A day for bathing.</b> Texts count a river bath at the saṅkrānti moment as especially purifying, and the giving of sesame, food, blankets and clothes as especially meritorious. Families who cannot travel bathe at home with sesame in the water.','<b>Prayāga.</b> At the confluence of the Gaṅgā and Yamunā the <b>Māgha Meḷa</b> begins around Saṅkrānti; every twelfth year it swells into the Kumbha Meḷa, the largest gathering of people on earth.','<b>Gaṅgāsāgar.</b> At the mouth of the Gaṅgā, pilgrims bathe where Bhagīratha’s river met the sea (previous pages tell why).','<b>In Karnataka.</b> Devotees bathe at the river confluences of the south, at Śrīraṅgapaṭṇa’s Kāvērī ghāṭs and Tirumakūḍalu Narasīpura’s triveṇī saṅgama. In Bengaluru crowds gather at the <b>Gavi Gaṅgādhareśvara</b> cave temple, where on Saṅkrānti evening the setting sun’s rays pass between Nandi’s horns onto the liṅga.'],[('z','The sun hits the liṅga exactly on Saṅkrānti?'),('b','Through Nandi’s horns, Zappy, for a few minutes. Thousands wait for it every year.')],'Bathe where <b>the waters meet</b>.'),
 reading('sesame','WHY SESAME AND JAGGERY','Winter food and old symbols',fig_row('Sesame seeds, jaggery, a sesame lamp and a blanket',[('<g>'+''.join(f'<ellipse cx="{x}" cy="{y}" rx="4" ry="2.4" fill="#f4ecd8"/>' for x,y in [(-8,-4),(0,-8),(8,-4),(-4,0),(4,0)])+'</g>',2),(jaggery(),2),(lamp(),1.8),('<rect x="-24" y="-24" width="48" height="24" fill="#c0392b"/><path d="M-24 -16 h48 M-24 -8 h48" stroke="#e0a800"/>',1.3)],['tila','bella','tila-dīpa','kambaḷi'],gy=150),['<b>Warmth.</b> Sesame and jaggery are winter foods: oily, warming and full of energy at the coldest time of the year. In Maharashtra people even wear black on Saṅkrānti to soak up the sun.','<b>Sacred sesame.</b> Sesame (<i>tila</i>) is used in offerings to the ancestors and in purification; one Purāṇic account says it sprang from Viṣṇu’s sweat. Gifts of sesame (<i>tila-dāna</i>) are prescribed for the day.','<b>Sweet speech.</b> Jaggery makes the sesame sweet, and every region turns it into a proverb: Karnataka’s “eat ellu-bella and speak good words”, Maharashtra’s “<i>tiḷgūḷ ghyā, goḍ goḍ bolā</i>”, take til-gul, speak sweetly.','<b>Mending.</b> The exchange is a social reset: you visit even the house you quarrelled with, and you cannot refuse a plate of ellu-bella.'],[('z','What if I’m angry with someone?'),('b','Take them ellu-bella anyway, Zappy. Saṅkrānti doesn’t ask whose fault it was.')],'Sweetness as <b>a duty</b>.'),
 reading('meaning','WHAT SAṄKRĀNTI MEANS','Gratitude to the sun',svg(560,150,'A farmer offering water to the rising sun over a field',f'<rect width="560" height="150" fill="#fde9c8"/>'+g(380,80,1.5,sun(28))+'<rect y="120" width="560" height="30" fill="#cfe0b8"/>'+g(200,122,1.2,namaste('#c0392b'))+'<path d="M222 70 q30 -10 60 0" stroke="#8fb8de" stroke-width="3" fill="none" stroke-dasharray="4 3"/>'),['<b>Thanksgiving.</b> Saṅkrānti thanks what feeds us: the sun, the rain, the soil, the cattle, the hands that harvested. The pongal pot boiling over is the image: abundance spilling out.','<b>Turning toward light.</b> The northern course is the year turning toward longer days. Many teachers read it as a call to turn the mind toward light, as Bhīṣma waited for it. (Interpretation.)','<b>Sweet relations.</b> The ellu-bella exchange makes the harvest social: food shared, words softened, quarrels ended.','<b>Keeping time.</b> As the one festival fixed by the sun, Saṅkrānti also keeps the calendar honest: it reminds us that the lunar months are always measured against the solar year.'],[('z','If I could do one thing for Saṅkrānti?'),('b','Offer water to the rising sun, Zappy, then take a plate of ellu-bella to someone you haven’t visited in a while.')],'Thank the sun, <b>sweeten the year</b>.'),
 end(i,['<b>When.</b> The sun enters Makara: 14 or 15 January.','<b>Meaning.</b> Uttarāyaṇa, the bright half of the year (Gītā 8.24).','<b>Stories.</b> Bhīṣma’s wait; the Gaṅgā at the sea; Sūrya visits Śani.','<b>Karnataka.</b> Ellu-bella, sakkare acchu, sugarcane, decorated cattle, kicchu.','<b>India.</b> Pongal, Lohri, Bihu, Uttarāyaṇ kites, Gaṅgāsāgar.'],'Previous: '+L('/festivals/panchanga/','the Pañcāṅga')+'. Next: '+L('/festivals/ratha-saptami/','Ratha Saptamī')+', the Sun’s chariot festival.','Makara Saṅkrānti: the sun turns north')]
pp.append(sources([('Astronomy and customs:','Wikipedia, “Makar Sankranti” (sidereal entry into Makara, drift from the solstice, regional names and customs, ellu bīrodu, til-gul, Uttarāyaṇ, Makaravilakku, Gaṅgāsāgar, Māgha Meḷa).'),('Texts:','Bhagavad Gītā 8.24 (BBT edition); Navagraha Stotra v. 1 attributed to Vyāsa (sanskritdocuments.org, hindutone.com); Mahābhārata, Bhīṣma and Anuśāsana parvans (Bhīṣma’s death); Rāmāyaṇa, Bāla Kāṇḍa and Bhāgavata 9 (Bhagīratha).')],'the Sūrya-Śani story (popular); kicchu hāyisuvudu and children’s customs (vary by village); the Gavi Gaṅgādhareśvara sun alignment (widely reported, not measured by us); sesame from Viṣṇu’s sweat (one Purāṇic account).','Gītā numbering as in the BBT edition.'))
build(i,'THE SUN TURNS NORTH · ELLU-BELLA · HARVEST',COV,'Sun, sugarcane and sesame','The <b>astronomy</b> told honestly, the stories of <b>Bhīṣma</b>, <b>Bhagīratha</b> and the Sun, the verses, and how <b>Karnataka</b> keeps ellu-bella, suggi and the cattle.','Makara Saṅkrānti explained: the sun entering Makara and uttarāyaṇa (Gītā 8.24), Bhīṣma on the bed of arrows, Bhagīratha and Gaṅgāsāgar, Sūrya and Śani, the Sūrya verse, Karnataka’s ellu bīruvudu, suggi and kicchu hāyisuvudu, Pongal, Lohri, Bihu and the kites.',pp)
